#!/usr/bin/env python3
from pathlib import Path
p=Path(__file__).resolve().parents[2]/'paper-reader-data.js'
s=p.read_text(encoding='utf-8')
start=s.index('"D2-PAPER-PROXY-REWARD-MEMORY-VARIANCE":{')
end=s.index(',\n"D2-PAPER-TEMPORAL-SKILL-CAUSAL-BOTTLENECK":{',start)
block=r'''"D2-PAPER-PROXY-REWARD-MEMORY-VARIANCE":{short:"Reward → Memory",question:{zh:"错误 terminal reward 会不会把同一 experience 写成不同 persistent state？而这种 state difference 在真实 retrieval/interface 下到底有多大 downstream transport？",en:"Can an erroneous terminal reward write different persistent state from the same experience, and how much of that state difference transports through the released retrieval/interface stack?"},conclusion:{zh:"write-time channel 很稳：原 4 个 complete pair + 16 个 fresh breadth pair 合计 20/20 全部分叉；stronger wording control 也不能吸收。forced memory swap 的 4×4 terminal test 能产生 |Δ|=.15625、p=.00074，但它不是 native retrieval。exact retriever audit 显示原 bank 只命中 8/188 held-out Shopping task，扩到 20 source 后为 125/172；在 36 个 pre-outcome native-hit task 上，288-call branch transport 只有 .02083（p=.4289），144-call no-memory presence 只有 .04514（p=.00147），两者都低于 .15 practical floor。",en:"The write-time channel is robust: the original four complete pairs plus sixteen fresh breadth pairs give 20/20 divergence, beyond the stronger wording control. A forced 4x4 terminal swap yields |delta|=.15625, p=.00074, but is not native retrieval. Exact retrieval hits only 8/188 held-out Shopping tasks with the original bank and 125/172 after expansion to 20 sources; on 36 pre-outcome native-hit tasks, 288-call branch transport is only .02083 (p=.4289) and 144-call no-memory presence only .04514 (p=.00147), both below the .15 practical floor."},science:{zh:"write identification + forced sensitivity + native transport boundary",en:"Write identification + forced sensitivity + native transport boundary"},method:[{zh:"byte-identical trajectory：只翻 success/failure writer branch；再用 16 个 fresh outcome-balanced source 做 breadth replication",en:"On byte-identical trajectories flip only the success/failure writer branch, then add a 16-source outcome-balanced breadth replication"},{zh:"用 stronger same-mode semantic-preserving wording control 排除 generic prompt sensitivity",en:"Use a stronger same-mode semantic-preserving wording control to challenge generic prompt sensitivity"},{zh:"把 forced memory swap 与 exact released MiniLM/top-1/.3 retrieval 分开；native-hit future 自动绑定 retriever-selected source",en:"Separate forced memory swaps from exact released MiniLM/top-1/.3 retrieval; native-hit futures are automatically bound to the retriever-selected source"},{zh:"同一 36-task support 上比较 success memory / failure memory / no-memory，并保持 .15 practical floor",en:"Compare success memory, failure memory, and no-memory on the same 36-task support while preserving the .15 practical floor"}],evidence:[{m:"20/20 · 0.673",t:{zh:"Write breadth",en:"Write breadth"},d:{zh:"20 个 complete paired source 全部 content/title 分叉；pooled token Jaccard=0.673。",en:"All 20 complete paired sources diverge in content/titles; pooled token Jaccard=0.673."}},{m:"0.15625 · p=.00074",t:{zh:"Forced terminal sensitivity",en:"Forced terminal sensitivity"},d:{zh:"4×4 fully crossed forced memory swap；证明 state 有 conditional leverage，但原四个 future 在原 bank 下 0/4 retrieval hit。",en:"Fully crossed 4x4 forced memory swap; establishes conditional leverage, but the four futures are 0/4 retrieval hits under the original bank."}},{m:"8/188 → 125/172",t:{zh:"Exact retrieval exposure",en:"Exact retrieval exposure"},d:{zh:"原 4-source bank hit rate 4.26%；20-source bank hit rate 72.7%，其中 36 task 可做 deterministic fixed-evidence terminal test。",en:"The original four-source bank hits 4.26%; the 20-source bank hits 72.7%, with 36 tasks eligible for deterministic fixed-evidence terminal testing."}},{m:"0.02083 · p=.4289",t:{zh:"Native branch transport",en:"Native branch transport"},d:{zh:"36 task / 288 calls；34/36 zero，18 个 joint floor + 16 个 joint ceiling；practical gate FAIL。",en:"36 tasks / 288 calls; 34/36 zero with 18 joint floors and 16 joint ceilings; practical gate FAIL."}},{m:"0.04514 · p=.00147",t:{zh:"Native memory presence",en:"Native memory presence"},d:{zh:"同 36 task 的 144-call no-memory arm；统计可见但低于 .15 floor。",en:"A 144-call no-memory arm on the same 36 tasks; statistically visible but below the .15 floor."}}],figure:{title:{zh:"Write 很稳，transport 有独立 gate",en:"Robust writing, separate transport gate"},groups:[{label:{zh:"Write support",en:"Write support"},items:[{label:{zh:"complete paired divergence",en:"complete paired divergence"},v:100,display:"20/20",role:"target"}]},{label:{zh:"Released retrieval exposure",en:"Released retrieval exposure"},items:[{label:{zh:"4-source bank",en:"4-source bank"},v:4.26,display:"8/188",role:"control"},{label:{zh:"20-source bank",en:"20-source bank"},v:72.67,display:"125/172",role:"target"}]},{label:{zh:"Terminal practical effect",en:"Terminal practical effect"},items:[{label:{zh:"forced swap",en:"forced swap"},v:15.625,display:"0.156",role:"target"},{label:{zh:"native branch",en:"native branch"},v:2.083,display:"0.021",role:"control"},{label:{zh:"native presence",en:"native presence"},v:4.514,display:"0.045",role:"control"}]}],note:{zh:"柱高不是同一统计样本：write 是 pair completion，retrieval 是 hit fraction，terminal 是 mean absolute effect。这里只用于展示 identification→exposure→transport 三层边界。",en:"Bar heights are not one statistical sample: writing is pair completion, retrieval is hit fraction, and terminal bars are mean absolute effects. The figure only visualizes the identification→exposure→transport decomposition."}},limitation:{zh:"原始 F0 两个 failure-arm provider incomplete 仍未恢复；native transport 仍是 fixed released evidence、不是 live browser；34/36 native cells 在 binary endpoint 上 branch-equivalent 且高度 floor/ceiling；DeepSeek cross-policy 在 900/2200 token 均首 unit length/no-text，0 scientific unit，只能记 support stop。",en:"Two original F0 failure-arm provider incompletions remain unresolved; native transport still uses fixed released evidence rather than a live browser; 34/36 native cells are branch-equivalent on a heavily floor/ceiling-saturated binary endpoint; DeepSeek cross-policy length-censors with no text on the first unit at both 900/2200 tokens, yielding zero scientific units and only a support stop."}}'''
s=s[:start]+block+s[end:]
p.write_text(s,encoding='utf-8')
print('updated reader expansion projection')
